// WhatsApp Support Agent: core logic (ported from main.py)
const FAQ = [
 {
  "intent": "price",
  "keywords": [
   "sneakers",
   "shoe",
   "shoes"
  ],
  "answer": "Our sneakers start from NGN 25,000. Full price list: https://example.com/prices"
 },
 {
  "intent": "price",
  "keywords": [
   "bag",
   "bags",
   "tote"
  ],
  "answer": "Bags range from NGN 18,000 to NGN 45,000 depending on size."
 },
 {
  "intent": "delivery",
  "keywords": [
   "lagos",
   "mainland",
   "island"
  ],
  "answer": "Lagos delivery takes 1-2 working days and costs NGN 3,500."
 },
 {
  "intent": "delivery",
  "keywords": [
   "abuja",
   "port",
   "harcourt",
   "outside"
  ],
  "answer": "Outside Lagos we deliver in 3-5 working days via GIG Logistics, from NGN 6,000."
 },
 {
  "intent": "returns",
  "keywords": [
   "return",
   "exchange",
   "size"
  ],
  "answer": "You can exchange unworn items within 7 days. Reply with your order number to start."
 }
];
const ORDERS = {
 "10234": {
  "status": "out for delivery",
  "eta": "today before 6pm"
 },
 "10235": {
  "status": "being packed",
  "eta": "tomorrow"
 },
 "10198": {
  "status": "delivered on 2026-10-03"
 }
};
// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const INTENTS = { complaint: ['not happy', 'complain', 'terrible', 'refund', 'wrong item', 'damaged', 'angry', 'scam'],
  order_status: ['order', 'where is my', 'track', 'status', 'delivered yet'], price: ['price', 'how much', 'cost'],
  delivery: ['deliver', 'shipping', 'lagos', 'abuja', 'how long'], returns: ['return', 'exchange'],
  greeting: ['hello', 'hi', 'good morning', 'good afternoon'] };
const classify = t => { t = t.toLowerCase();
  for (const [k, ws] of Object.entries(INTENTS)) if (ws.some(w => t.includes(w))) {
    if (k === 'order_status' && !/\d{4,}/.test(t) && !t.includes('where is my')) continue; return k; }
  return 'unknown'; };
const out = [];
for (const m of input) {
  const text = m.text || '', intent = classify(text);
  let reply, handover = false;
  if (intent === 'order_status') { const n = (text.match(/(\d{4,})/) || [])[1], o = n && ORDERS[n];
    reply = o ? `Order ${n} is ${o.status}${o.eta ? ', expected ' + o.eta : ''}.` : "Please send your order number (e.g. 10234) and I'll check it right away."; }
  else if (['complaint', 'unknown'].includes(intent)) { handover = true; reply = "I'm sorry about this. I've passed your message to our team, who will reply shortly."; }
  else if (intent === 'greeting') reply = 'Hi! How can we help today? You can ask about prices, delivery or your order.';
  else { const ws = new Set(text.toLowerCase().match(/[a-z]+/g) || []); const c = FAQ.filter(f => f.intent === intent);
    const best = c.sort((a, b) => b.keywords.filter(k => ws.has(k)).length - a.keywords.filter(k => ws.has(k)).length)[0];
    reply = best ? best.answer : null; handover = !best; }
  out.push({ route: handover ? 'handover' : 'reply', to: m.from, intent, customer_message: text, message: reply });
}
return out.map(json => ({ json }));
